/*
 * Compatibility shim for legacy script-based THREE usage.
 * The game now relies on ESM import maps in index.html.
 */
(function () {
  if (typeof window === 'undefined' || window.THREE) return;

  import('https://unpkg.com/three@0.170.0/build/three.module.js')
    .then((mod) => {
      window.THREE = mod;
    })
    .catch((err) => {
      console.error('Failed to load THREE compatibility module:', err);
    });
})();
